<script>
import api from '../api.js';
import ConfiguredForm from './ConfiguredForm.vue';
export default {
 name:'CollectionPanel',components:{ConfiguredForm},props:{project:String,target:String,selectedKeys:{type:Array,default:()=>[]},refreshKey:Number},emits:['changed','open'],
 data(){return {catalog:{items:[],total:0,offset:0,limit:40},members:null,trail:[],keyword:'',error:'',busy:false,memberSelection:[],form:null,formError:'',addDialog:false,candidates:{items:[],total:0,offset:0,limit:40},candidateKeyword:'',candidateSelection:[],deleteDialog:false,seq:0,alive:true}},
 watch:{refreshKey(){this.reload()}},
 mounted(){this.load()},beforeUnmount(){this.alive=false;this.seq++},
 methods:{
 async reload(){await this.load(this.catalog.offset);if(this.members)await this.page(this.members.offset)},
 args(extra={}){return {project:this.project,target:this.target,...extra}},
 isCollection(row){return [true,1,'true','t'].includes(row.values._is_collection)},
 title(row){return row.values.name||row.values.code},
 async load(offset=0){const seq=++this.seq;this.busy=true;this.error='';try{const d=await api.request('/collections',this.args({offset,limit:40,keyword:this.keyword}));if(!this.alive||seq!==this.seq)return;this.catalog=d;if(d.fixed_collection&&!this.members)await this.enter(d.fixed_collection,true)}catch(e){if(this.alive&&seq===this.seq)this.error=e.message}finally{if(this.alive&&seq===this.seq)this.busy=false}},
 async enter(row,replace=false){if(this.busy&&this.members)return;this.busy=true;this.error='';try{const d=await api.request('/collection-members',this.args({collection:row.key,offset:0,limit:40}));if(!this.alive)return;this.members=d;this.memberSelection=[];if(replace)this.trail=[d.collection];else this.trail.push(d.collection)}catch(e){if(this.alive)this.error=e.message}finally{if(this.alive)this.busy=false}},
 async page(offset=0){this.busy=true;this.error='';try{const d=await api.request('/collection-members',this.args({collection:this.members.collection.key,offset,limit:40}));if(this.alive){this.members=d;this.memberSelection=[]}}catch(e){if(this.alive)this.error=e.message}finally{if(this.alive)this.busy=false}},
 async back(index){if(index<0){this.members=null;this.trail=[];this.memberSelection=[];return}const row=this.trail[index];this.trail=this.trail.slice(0,index);await this.enter(row)},
 async findCandidates(offset=0){this.error='';try{this.candidates=await api.request('/collections',this.args({mode:'records',keyword:this.candidateKeyword,offset,limit:40}))}catch(e){this.error=e.message}},
 async adding(){this.addDialog=true;this.candidateSelection=[];await this.findCandidates()},
 async change(action,keys=[]){this.error='';this.busy=true;try{await api.request('/collection-change',this.args({collection:this.members.collection.key,revision:this.members.revision,action,keys,confirm:action==='delete'?'DELETE_COLLECTION':undefined}),'POST');this.addDialog=false;this.deleteDialog=false;if(action==='delete'){this.members=null;this.trail=[];await this.load()}else await this.page();this.$emit('changed')}catch(e){this.error=e.message}finally{this.busy=false}},
 create(){this.form=this.catalog.create_form;this.formError=''},
 async save(values){this.busy=true;this.formError='';try{const result=await api.request('/collections',this.args({values,collection:this.members?.collection.key,revision:this.members?.revision}),'POST');this.form=null;if(this.members)await this.page();else await this.load();this.$emit('changed')}catch(e){this.formError=e.message}finally{this.busy=false}},
 toggle(list,key,checked){const i=list.indexOf(key);if(checked&&i<0)list.push(key);else if(!checked&&i>=0)list.splice(i,1)},
 openObjects(){if(this.catalog.records_target)this.$emit('open',{id:this.catalog.records_target})}
 }
};
</script>
<template>
<section class="collection-panel" aria-label="Коллекции объектов"><header class="widget-toolbar" role="group" aria-label="Действия с коллекциями"><code class="editor-context" :title="catalog.instance_type">{{catalog.search_type}}</code><div class="toolbar"><button v-if="catalog.records_target" @click="openObjects">Таблица объектов</button><button :disabled="busy||!catalog.can_create" @click="create">{{members?'Новая вложенная коллекция':'Новая коллекция'}}</button></div></header><p class="notice">{{catalog.notice}}</p><p v-if="error" class="error">{{error}}</p>
<nav class="collection-breadcrumb"><button v-if="!catalog.fixed_collection" @click="back(-1)">Все коллекции</button><template v-for="(row,i) in trail" :key="row.key"><span>›</span><button :disabled="i===trail.length-1||busy" @click="back(i)">{{title(row)}}</button></template></nav>
<template v-if="!members"><form class="toolbar" @submit.prevent="load()"><input v-model="keyword" placeholder="Название коллекции" aria-label="Найти коллекцию"><button :disabled="busy">Найти</button></form><div class="collection-grid"><button v-for="row in catalog.items" :key="row.key" class="collection-card" :disabled="busy" @click="enter(row)"><span class="eyebrow">КОЛЛЕКЦИЯ</span><b>{{title(row)}}</b><small>{{row.values.description||row.values.code}}</small></button></div><p v-if="!catalog.items.length&&!busy" class="muted">Коллекций не найдено.</p><footer class="toolbar"><small>{{catalog.total}} коллекций · {{catalog.offset+1}}–{{catalog.offset+catalog.items.length}}</small><span class="spacer"></span><button :disabled="busy||!catalog.offset" @click="load(Math.max(0,catalog.offset-40))">Назад</button><button :disabled="busy||!catalog.has_more" @click="load(catalog.offset+40)">Далее</button></footer></template>
<template v-else><header><div><h3>{{title(members.collection)}}</h3><p>{{members.collection.values.description}}</p><small>{{members.total}} объектов · {{members.links}} instance-связей · родителей: {{members.parents}}</small></div></header>
<p v-if="members.duplicate_links||members.missing_members" class="notice">Повторных связей: {{members.duplicate_links}}; отсутствующих объектов: {{members.missing_members}}. Диагностика не исправляет данные автоматически.</p>
<div class="toolbar"><button :disabled="busy||!members.can_write" @click="adding">Добавить существующие</button><button v-if="selectedKeys.length" :disabled="busy||!members.can_write||selectedKeys.length>100" @click="change('add',selectedKeys)">Добавить выбранные в таблице ({{selectedKeys.length}})</button><button :disabled="busy||!members.can_write||!memberSelection.length" @click="change('remove',memberSelection)">Убрать из коллекции ({{memberSelection.length}})</button><span class="spacer"></span><button :disabled="busy||!members.can_write" @click="deleteDialog=true">Удалить коллекцию…</button></div>
<div class="collection-members"><article v-for="row in members.items" :key="row.key" class="collection-member"><label><input type="checkbox" :checked="memberSelection.includes(row.key)" :disabled="busy" @change="toggle(memberSelection,row.key,$event.target.checked)"><span v-if="isCollection(row)" class="tag">коллекция</span><b>{{title(row)}}</b></label><span v-if="row.values.s_status==='retired'" class="tag">архив</span><small>{{row.values.code}}</small><button v-if="isCollection(row)" :disabled="busy||row.values.s_status==='retired'||!!catalog.fixed_collection" @click="enter(row)">Открыть вложенную</button></article></div><p v-if="!members.items.length" class="muted">Коллекция пуста.</p><footer class="toolbar"><small>{{members.offset+(members.total?1:0)}}–{{members.offset+members.items.length}} из {{members.total}}</small><span class="spacer"></span><button :disabled="busy||!members.offset" @click="page(Math.max(0,members.offset-40))">Назад</button><button :disabled="busy||!members.has_more" @click="page(members.offset+40)">Далее</button></footer><p class="muted">{{members.notice}}</p></template>
<ConfiguredForm v-if="form" :form="form" :busy="busy" :error="formError" @save="save" @close="form=null"/>
<Teleport to="body"><div v-if="addDialog" class="modal-backdrop"><section class="modal collection-add" role="dialog"><header><h3>Добавить существующие объекты</h3><button @click="addDialog=false">×</button></header><p>Создаётся только instance-связь. Объект и его файлы не копируются.</p><p v-if="error" class="error">{{error}}</p><form class="toolbar" @submit.prevent="findCandidates()"><input v-model="candidateKeyword" placeholder="Название объекта" aria-label="Поиск кандидатов"><button>Найти</button></form><div class="candidate-list"><label v-for="row in candidates.items" :key="row.key"><input type="checkbox" :checked="candidateSelection.includes(row.key)" :disabled="row.key===members.collection.key" @change="toggle(candidateSelection,row.key,$event.target.checked)"><b>{{title(row)}}</b><small>{{isCollection(row)?'коллекция':'объект'}} · {{row.values.code}}</small></label></div><div class="toolbar"><small>{{candidates.offset+1}}–{{candidates.offset+candidates.items.length}} из {{candidates.total}}</small><button :disabled="!candidates.offset" @click="findCandidates(Math.max(0,candidates.offset-40))">Назад</button><button :disabled="!candidates.has_more" @click="findCandidates(candidates.offset+40)">Далее</button></div><footer><small>{{candidateSelection.length}} выбрано · до 100 за операцию</small><button class="primary" :disabled="busy||!candidateSelection.length||candidateSelection.length>100" @click="change('add',candidateSelection)">Добавить связи</button></footer></section></div>
<div v-if="deleteDialog" class="modal-backdrop"><section class="modal collection-delete" role="dialog"><header><h3>Удалить коллекцию «{{title(members.collection)}}»?</h3><button @click="deleteDialog=false">×</button></header><p>Штатный CollectionDeleteCmd удалит саму запись коллекции и входящие/исходящие связи. Содержимое коллекции — {{members.total}} объектов — эта команда напрямую не удаляет. Пользовательские серверные триггеры остаются действующими.</p><p v-if="error" class="error">{{error}}</p><footer><button @click="deleteDialog=false">Отмена</button><button class="danger" :disabled="busy" @click="change('delete')">Удалить коллекцию и её связи</button></footer></section></div></Teleport></section>
</template>
